  teaching: {
    paragraphs: [
      "A random variable assigns a number to the outcome of a random process. It is discrete if its possible values can be listed — the number of heads in three tosses can only be 0, 1, 2 or 3. It is continuous if it can take any value in an interval — the time a runner takes, a person's height, the weight of an apple. Between any two times like 11.2 s and 11.3 s there are infinitely many possible values, so we cannot list them.",
      "This creates a problem. For a discrete variable we give each value a probability and the probabilities add to 1. For a continuous variable there are infinitely many values, so if every single value had the same positive probability, the total would be infinite. The only way the total can stay 1 is for the probability of any exact value to be 0. So we stop asking 'what is the probability X equals exactly 11.234...?' and instead ask 'what is the probability X lands in an interval?'",
      "To see how, start with data. Build a relative-frequency histogram so that the area of each bar (not its height) equals the proportion of data in that interval — then the total area of all bars is 1. Now collect more data and make the bars narrower. The tops of the bars settle down to a smooth curve. That limiting curve is the probability density function, written $f(x)$, and the rule it inherits from the histogram is the key idea: probability is the area under the curve.",
      "So for a continuous random variable, $P(a<X<b)$ is the area under $y=f(x)$ between $x=a$ and $x=b$, which we compute as the definite integral $\\int_a^b f(x)\\,dx$. Because the area sitting above a single point $x=a$ is a line of zero width and therefore zero area, $P(X=a)=0$. A direct and useful consequence: the endpoints never matter, so $P(a<X<b)=P(a\\le X\\le b)$. Swapping $<$ for $\\le$ changes nothing for a continuous variable.",
      "Every PDF must satisfy two properties, and both come straight from what probability means. First, $f(x)\\ge 0$ for all $x$: an area representing a probability can never be negative. Second, the total area is 1: $\\int_{-\\infty}^{\\infty} f(x)\\,dx=1$, because the variable must take some value. In practice $f(x)$ is only non-zero on some interval $[a,b]$ (its support), and is 0 elsewhere, so the total area is just $\\int_a^b f(x)\\,dx=1$. This second property is the workhorse: when a PDF contains an unknown constant $k$, you find $k$ by setting the total area equal to 1 and solving.",
      "A warning that catches many students: $f(x)$ is a density, not a probability. The height $f(x)$ can be larger than 1 — for example $f(x)=3x^2$ on $[0,1]$ reaches $f(1)=3$ — and that is perfectly valid, because what must be $\\le 1$ is the area, not the height. Never read a value of $f$ as 'the probability of that value'; the probability of any single value is 0.",
      "The simplest continuous model is the continuous uniform distribution, where $X$ is equally likely to fall anywhere in $[a,b]$. 'Equally likely everywhere' means a flat density: $f(x)$ is the same constant height across the whole interval. Since the region is a rectangle of width $b-a$ and the area must be 1, the height must be $\\dfrac{1}{b-a}$. For a uniform variable, the probability of an interval is just the fraction of the total length it covers.",
      "Finally, the mode of a continuous random variable is the value of $x$ where the density $f(x)$ is greatest — the peak of the curve, the most concentrated region of probability. If $f$ is increasing across its whole support, the mode is the right endpoint; if decreasing, the left endpoint; otherwise it is found where $f'(x)=0$ gives the maximum.",
    ],
    latexBlocks: [
      "f(x)\\ge 0 \\quad\\text{for all }x",
      "\\int_{-\\infty}^{\\infty} f(x)\\,dx=1 \\quad\\Big(\\text{or }\\int_a^b f(x)\\,dx=1\\text{ on the support }[a,b]\\Big)",
      "P(a<X<b)=\\int_a^b f(x)\\,dx",
      "P(X=a)=0 \\;\\Rightarrow\\; P(a<X<b)=P(a\\le X\\le b)",
      "\\text{Continuous uniform on }[a,b]: \\quad f(x)=\\frac{1}{b-a}",
    ],
  },
  workedExamples: [
    {
      title: "Worked example 1: Find an unknown constant in a PDF",
      questionLatex:
        "f(x)=kx \\text{ for } 0\\le x\\le 4 \\text{ (and }f(x)=0\\text{ otherwise). Find }k.",
      steps: [
        {
          explanation:
            "Use the total-area property: the integral of the PDF over its support must equal 1.",
          latex: "\\int_0^4 kx\\,dx=1",
        },
        {
          explanation: "Integrate, taking the constant $k$ outside.",
          latex: "k\\left[\\frac{x^2}{2}\\right]_0^4=k\\cdot\\frac{16}{2}=8k",
        },
        {
          explanation: "Set equal to 1 and solve for $k$.",
          latex: "8k=1 \\;\\Rightarrow\\; k=\\frac{1}{8}",
        },
      ],
      finalAnswerLatex: "k=\\frac{1}{8}",
    },
    {
      title: "Worked example 2: A probability as an area",
      questionLatex:
        "f(x)=\\frac{x}{8} \\text{ for } 0\\le x\\le 4. \\text{ Find }P(1<X<3).",
      steps: [
        {
          explanation:
            "The probability is the area under the curve between 1 and 3, so integrate the PDF over $[1,3]$.",
          latex: "P(1<X<3)=\\int_1^3 \\frac{x}{8}\\,dx",
        },
        {
          explanation: "Integrate term by term.",
          latex: "=\\frac{1}{8}\\left[\\frac{x^2}{2}\\right]_1^3=\\frac{1}{8}\\cdot\\frac{9-1}{2}",
        },
        {
          explanation: "Evaluate.",
          latex: "=\\frac{1}{8}\\cdot 4=\\frac{1}{2}",
        },
      ],
      finalAnswerLatex: "P(1<X<3)=\\frac{1}{2}",
    },
    {
      title: "Worked example 3: Continuous uniform distribution",
      questionLatex:
        "X \\text{ is uniformly distributed on } [2,10]. \\text{ State }f(x)\\text{ and find }P(X<5).",
      steps: [
        {
          explanation:
            "For a uniform distribution the density is the reciprocal of the interval width.",
          latex: "f(x)=\\frac{1}{10-2}=\\frac{1}{8}",
        },
        {
          explanation:
            "$P(X<5)$ is the fraction of the interval from 2 to 5 — a rectangle of width 3 and height $\\tfrac{1}{8}$.",
          latex: "P(X<5)=\\frac{5-2}{8}=\\frac{3}{8}",
        },
      ],
      finalAnswerLatex: "f(x)=\\frac{1}{8},\\quad P(X<5)=\\frac{3}{8}",
    },
    {
      title: "Worked example 4: Density above 1, and the mode",
      questionLatex:
        "f(x)=3x^2 \\text{ for } 0\\le x\\le 1. \\text{ Verify it is a PDF, state the mode, and find }P(X>0.5).",
      steps: [
        {
          explanation:
            "Check the total area is 1. (It is non-negative on $[0,1]$, so the first property holds.)",
          latex: "\\int_0^1 3x^2\\,dx=\\left[x^3\\right]_0^1=1\\;\\checkmark",
        },
        {
          explanation:
            "Note $f(1)=3>1$ — that is allowed, because a density is not a probability; only the area must be $\\le 1$. The mode is where $f$ is greatest: $f$ increases across $[0,1]$, so the peak is at the right endpoint.",
          latex: "\\text{mode}=1",
        },
        {
          explanation:
            "$P(X>0.5)$ is the area from 0.5 to 1.",
          latex: "P(X>0.5)=\\int_{0.5}^{1} 3x^2\\,dx=\\left[x^3\\right]_{0.5}^{1}=1-0.125=0.875",
        },
      ],
      finalAnswerLatex: "\\text{PDF }\\checkmark,\\quad \\text{mode}=1,\\quad P(X>0.5)=0.875",
    },
  ],
